// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address adminAddr = address(0xABCD);

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address candidateOwner) public {

        vm.deal(adminAddr, 1 ether);

        vm.prank(address(this));
        bool ok;
        try c.setOwner(candidateOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.owner() == candidateOwner);
        } else {
            assertTrue(c.owner() == c.owner());
        }
    }
}
